interface DatedHold {
  from: string;
  to: string | null;
}

/** Whether a day lies within one of the person's holds. */
function heldOn(p: Person, date: string): boolean {
  return p.holds.some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** Whether the person's retirement date is reached on a day (the day on or after it). */
function retiredOn(p: Person, date: string | null): boolean {
  return p.retiredFrom !== null && date !== null && date >= p.retiredFrom;
}

/**
 * Whether a claim of the person counts toward the totals: an OPEN or PENDING claim that is held, or
 * dated within one of their holds, does not, nor does one once the sheet's today reaches their retirement date, unless
 * a statement binds it; nor does a claim deferred on the sheet's today.
 */
function countsFor(p: Person | undefined, c: Claim, today: string | null): boolean {
  return counts(c) && !deferred(c, today)
    && (c.stated || !(isOpen(c) && (c.held || (p !== undefined && (heldOn(p, c.date) || retiredOn(p, today))))));
}

/**
 * Whether a claim of the person counts toward claimed: as {@link countsFor}, but a hold (the person's
 * or the claim's) does not take it out; only its due figures leave the totals while held.
 */
function claimedFor(p: Person | undefined, c: Claim, today: string | null): boolean {
  return counts(c) && !deferred(c, today)
    && (c.stated || !(isOpen(c) && p !== undefined && retiredOn(p, today)));
}

/** One of a person's patrons. */
interface PatronLink {
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>('/api/claims/hold', { sheet, user: this.session.user(), id: c.id }),
      );
      if (this.session.sheet() !== sheet) return;
      this.saved.emit(claim);
    } catch (e) {
      if (this.session.sheet() !== sheet) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      const err =
        status === 409
          ? `A ${c.status} claim cannot be held or released.`
          : c.held
            ? 'Could not release this claim.'
            : 'Could not hold this claim.';
      this.actionErrors.update((m) => new Map(m).set(c.id, err));
    }
  }

  /** Move a claim to its next status; the server refuses a move its status does not allow. */
  protected async act(c: Claim, action: ClaimAction): Promise<void> {
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetHistory;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total
 * (the figures of their overdue claims that count, not capped), and the sheet's totals of each. A change takes a {@link #snapshot} before it alters anything
 * and calls {@link #recordChanges} after its own audit lines, which appends one ROLLUP line per
 * person whose figures moved (people in the order they were added; a new person counts as moved),
 * then a TOTALS line when any of the sheet's totals moved. A held person's OPEN claims (and PENDING ones), and a
 * held claim, count in claimed but in none of the due figures, nor in a period's due-total; their SETTLED claims count in all. So too a person whose
 * retirement date the sheet's today has reached. An overdue claim's figure has
 * its late charge added on top, and a live due is then never below the floor in force on its claim's date. A person's
 * due-total is at most the cap in force on the sheet's today, when there is one. With an alert threshold
 * set, the rollup lines are followed by one ALERT line per person (in list order) whose due-total went
 * from at or below it (or none) to above it.
 */
@Service
public class RollupService {

        Sheet sheet = sheet(sheetId);
        LocalDate today = sheet.getToday();
        List<List<Rate>> sheetRates = rates.current(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
